INSERT INTO _migration_612_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_electricity_s3_001', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which quantity is measured in amperes?', 'multiple_choice', NULL, '["A. Potential difference","B. Electric current","C. Resistance","D. Electric charge"]', 'B', 'The ampere (A) is the SI unit of electric current, which is the rate of flow of charge: I = Q ÷ t. Potential difference is measured in volts, resistance in ohms, and charge in coulombs. Therefore the correct answer is B: Electric current.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_002', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which arrangement is used to measure the potential difference across a fixed resistor in a circuit?', 'multiple_choice', NULL, '["A. A voltmeter connected in series with the resistor","B. An ammeter connected in parallel with the resistor","C. A voltmeter connected in parallel with the resistor","D. An ammeter connected in series with the resistor"]', 'C', 'Potential difference is measured across a component, so the voltmeter is connected in parallel with it. An ammeter measures the current through the circuit and must be connected in series; connecting an ammeter in parallel would short-circuit the resistor. Therefore the correct answer is C: A voltmeter connected in parallel with the resistor.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_003', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A current of 2.0 A flows through a resistor when the potential difference across it is 12 V. Calculate the resistance of the resistor.', 'multiple_choice', NULL, '["A. 24 Ω","B. 0.17 Ω","C. 10 Ω","D. 6.0 Ω"]', 'D', 'From V = IR, the resistance is R = V ÷ I = 12 ÷ 2.0 = 6.0 Ω. (24 Ω multiplies instead of dividing; 0.17 Ω inverts the ratio to I/V; 10 Ω subtracts the current from the voltage.) Therefore the correct answer is D: 6.0 Ω.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_004', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Two resistors of resistance 4.0 Ω and 6.0 Ω are connected in series across a 20 V supply. Calculate the current in the circuit.', 'multiple_choice', NULL, '["A. 2.0 A","B. 5.0 A","C. 3.3 A","D. 0.50 A"]', 'A', 'Resistors in series add: R = 4.0 + 6.0 = 10 Ω. The current is I = V ÷ R = 20 ÷ 10 = 2.0 A. (5.0 A uses only the 4.0 Ω resistor and 3.3 A only the 6.0 Ω resistor — both ignore the series combination; 0.50 A inverts V/R.) Therefore the correct answer is A: 2.0 A.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_005', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which material is most suitable for the core of an electromagnet that must switch on and off rapidly?', 'multiple_choice', NULL, '["A. Steel, because it retains its magnetism permanently","B. Soft iron, because it magnetises and demagnetises easily","C. Copper, because it is a good electrical conductor","D. Aluminium, because it is light and does not rust"]', 'B', 'An electromagnet core must be a soft magnetic material: soft iron magnetises strongly while the current flows and loses its magnetism almost as soon as the current is switched off. Steel is a hard magnetic material that retains its magnetism, and copper and aluminium are not magnetic at all. Therefore the correct answer is B: Soft iron, because it magnetises and demagnetises easily.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_006', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A transformer has 500 turns on its primary coil and 100 turns on its secondary coil. The primary voltage is 230 V. Calculate the secondary voltage.', 'multiple_choice', NULL, '["A. 1,150 V","B. 23 V","C. 46 V","D. 460 V"]', 'C', 'For a transformer, Vs ÷ Vp = Ns ÷ Np, so Vs = 230 × (100 ÷ 500) = 230 × 0.2 = 46 V. (1,150 V inverts the turns ratio, stepping the voltage up instead of down; 23 V divides by 10 unnecessarily; 460 V doubles the correct value.) Therefore the correct answer is C: 46 V.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_007', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'What is the function of the split-ring commutator in a simple d.c. electric motor?', 'multiple_choice', NULL, '["A. It increases the current flowing through the coil","B. It prevents the wires from the battery from touching the coil","C. It converts the direct current into alternating current","D. It reverses the direction of the current in the coil every half turn, so the coil keeps rotating in the same direction"]', 'D', 'When the coil passes the vertical position the split ring swaps the connections to the brushes, reversing the current in the coil every half turn. This keeps the turning force acting in the same sense, so the coil rotates continuously instead of oscillating back and forth. Therefore the correct answer is D: It reverses the direction of the current in the coil every half turn, so the coil keeps rotating in the same direction.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_008', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Two 12 Ω resistors connected in parallel are joined in series with a 6.0 Ω resistor across a 12 V battery. Calculate the current supplied by the battery.', 'multiple_choice', NULL, '["A. 1.0 A","B. 2.0 A","C. 0.40 A","D. 0.67 A"]', 'A', 'The parallel pair has resistance (1/12 + 1/12)⁻¹ = 6.0 Ω, so the total resistance is 6.0 + 6.0 = 12 Ω and the battery current is I = V ÷ R = 12 ÷ 12 = 1.0 A. (2.0 A ignores the parallel pair entirely; 0.40 A wrongly adds the two 12 Ω resistors in series to give 30 Ω; 0.67 A uses 18 Ω, keeping one 12 Ω resistor.) Therefore the correct answer is A: 1.0 A.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_612_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_612_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_612_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_612_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_612_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_612_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_612_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_612_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_612_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_612_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
